mapper.select:
select a.id BORKEN_ID,a.ALARM_STATE borken_alarm_state,a.status as alarm_status,

a.content borken_content,d.broken_record_id list_id,a.TITLE as title,A.ALARM_LEVEL AS ALARM_LEVEL,
d.solve_status,
d.opinion list_opinion,d.create_time list_createTime,d.creator list_creator
from (
select alarm_info.*,asset.name,asset.asset_mode from alarm_info,asset where alarm_info.asset_id=asset.id

    and asset.asset_mode = #{assetMode}

) a
left join
(select b.alarm_id,b.status as solve_status, c.* from BROKEN_RECORD b
left join BROKEN_RECORD_OPINION c on b.id=c.BROKEN_RECORD_ID) d on a.id=d.alarm_id
where rownum < 20000

    and a.org_id = #{orgId}


    and a.org_id in

        #{id}



    and REGEXP_INSTR(a.asset_ip, #{assetIp})>0


    and REGEXP_INSTR(a.name, #{assetName})>0


    and REGEXP_INSTR(a.TITLE, #{title})>0


    and a.status = #{status}


    and a.alarm_code = #{eventCategory}


    and a.alarm_level = #{alarmLevel}


    and a.type = #{type}


    and a.occur_time between #{startTime} and #{endTime}


    and a.asset_mode = #{assetMode}

order by a.occur_time desc

SELECT a.id AS BORKEN_ID, a.ALARM_STATE AS borken_alarm_state, a.status AS alarm_status, a.content AS borken_content, d.broken_record_id AS list_id, a.TITLE AS title, a.ALARM_LEVEL AS ALARM_LEVEL, d.solve_status, d.opinion AS list_opinion, d.create_time AS list_createTime, d.creator AS list_creator FROM ( SELECT alarm_info.*, asset.name, asset.asset_mode FROM alarm_info JOIN asset ON alarm_info.asset_id = asset.id
AND asset.asset_mode = #{assetMode}
) a LEFT JOIN ( SELECT b.alarm_id, b.status AS solve_status, c.* FROM BROKEN_RECORD b LEFT JOIN BROKEN_RECORD_OPINION c ON b.id = c.BROKEN_RECORD_ID ) d ON a.id = d.alarm_id WHERE rownum < 20000
AND a.org_id = #{orgId}
AND a.org_id IN
#{id}
AND REGEXP_INSTR(a.asset_ip, #{ip}) > 0
AND REGEXP_INSTR(a.name, #{assetName}) > 0
AND REGEXP_INSTR(a.TITLE, #{title}) > 0
AND a.status = #{status}
AND a.ALARM_LEVEL IN
#{id}
AND a.ALARM_CODE IN
#{id}
AND a.type = #{type}
AND a.occur_time BETWEEN #{startDate} AND #{endDate}
ORDER BY a.occur_time DESC
